cmp.addEventListener("keydown", (ev) => {
  const current_split = parseFloat(cmp.style.getPropertyValue("--split")) || 50;
  let next = current_split;
  if (ev.key === "ArrowLeft") next = current_split - 5;
  else if (ev.key === "ArrowRight") next = current_split + 5;
  else if (ev.key === "Home") next = 0;
  else if (ev.key === "End") next = 100;
  else return;
  ev.preventDefault();
  cancelAnimationFrame(raf);
  setSplit(next);
});
```

